IF OBJECT_ID(N'dbo.tb_Auth_LoginSession', N'U') IS NULL CREATE TABLE dbo.tb_Auth_LoginSession (Id uniqueidentifier NOT NULL PRIMARY KEY, UserId bigint NOT NULL, SecurityVersion bigint NOT NULL, CreatedAt datetime2 NOT NULL, ExpiresAt datetime2 NOT NULL, RevokedAt datetime2 NULL);
IF OBJECT_ID(N'dbo.tb_Auth_TenantContext', N'U') IS NULL CREATE TABLE dbo.tb_Auth_TenantContext (Id uniqueidentifier NOT NULL PRIMARY KEY, UserId bigint NOT NULL, SessionId uniqueidentifier NOT NULL, TenantId bigint NOT NULL, CreatedAt datetime2 NOT NULL, ExpiresAt datetime2 NOT NULL, RevokedAt datetime2 NULL);
IF OBJECT_ID(N'dbo.tb_Auth_LoginIdentifier', N'U') IS NULL CREATE TABLE dbo.tb_Auth_LoginIdentifier (NormalizedValue nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY, UserId bigint NOT NULL, IsUserName bit NOT NULL, IsEmail bit NOT NULL);
IF OBJECT_ID(N'dbo.tb_Auth_GrantDepartment', N'U') IS NULL CREATE TABLE dbo.tb_Auth_GrantDepartment (GrantId bigint NOT NULL, DepartmentId bigint NOT NULL, TenantId bigint NOT NULL, PRIMARY KEY(GrantId,DepartmentId));
IF OBJECT_ID(N'dbo.tb_Auth_AuditEvent', N'U') IS NULL CREATE TABLE dbo.tb_Auth_AuditEvent (Id uniqueidentifier NOT NULL PRIMARY KEY, UserId bigint NULL, SessionId uniqueidentifier NULL, TenantId bigint NULL, AppsId bigint NULL, ContextId uniqueidentifier NULL, Action nvarchar(160) NOT NULL, TargetType nvarchar(80) NOT NULL, TargetId nvarchar(80) NULL, Result nvarchar(20) NOT NULL, CreatedAt datetime2 NOT NULL, TraceId nvarchar(100) NOT NULL, Summary nvarchar(max) NOT NULL);
IF OBJECT_ID(N'dbo.tb_Auth_AuditOutbox', N'U') IS NULL CREATE TABLE dbo.tb_Auth_AuditOutbox (Id uniqueidentifier NOT NULL PRIMARY KEY, Payload nvarchar(max) NOT NULL, CreatedAt datetime2 NOT NULL, DispatchedAt datetime2 NULL);
IF OBJECT_ID(N'dbo.tb_Auth_MigrationIssue', N'U') IS NULL CREATE TABLE dbo.tb_Auth_MigrationIssue (Id bigint IDENTITY(1,1) NOT NULL PRIMARY KEY, Resource nvarchar(128) NOT NULL, RecordId bigint NOT NULL, Reason nvarchar(512) NOT NULL, ResolvedAt datetime2 NULL);
IF OBJECT_ID(N'dbo.tb_Auth_SchemaVersion', N'U') IS NULL CREATE TABLE dbo.tb_Auth_SchemaVersion (Version int NOT NULL PRIMARY KEY, AppliedAt datetime2 NOT NULL, ManifestHash nvarchar(64) NOT NULL);
